-- Deadmines heroic: creature templates were level 1 friendly placeholders without damage or loot
-- Idempotent: every INSERT is preceded by a DELETE of its keys.

-- creature_template
DELETE FROM `creature_template` WHERE `entry` IN (900166,900167,900168,900169);

-- creature_template updates (difficulty slots, loot ids, SmartAI)
UPDATE `creature_template` SET `difficulty_entry_1`=900166 WHERE `entry`=47714;
UPDATE `creature_template` SET `difficulty_entry_1`=900167 WHERE `entry`=49850;
UPDATE `creature_template` SET `difficulty_entry_1`=900168 WHERE `entry`=49852;
UPDATE `creature_template` SET `difficulty_entry_1`=900169 WHERE `entry`=49854;

-- creature_template (rebuilt placeholder difficulty templates)
DELETE FROM `creature_template` WHERE `entry` IN (48777,48778,48779,48781,48782,48787,48791,48792,48803,48804,48810,48811,48812,48814,48819,48820,48821,48823,48824,48826,48827,48829,48830,48834,48835,48913,48914,48936,48939,48940,48941,48943,48944);

-- creature_template levels (normal difficulty)
UPDATE `creature_template` SET `minlevel`=21, `maxlevel`=24 WHERE `entry`=46613;
UPDATE `creature_template` SET `minlevel`=9, `maxlevel`=9 WHERE `entry`=48284;
UPDATE `creature_template` SET `minlevel`=10, `maxlevel`=10 WHERE `entry`=48445;

-- creature_loot_template (23 loot ids)
DELETE FROM `creature_loot_template` WHERE `entry` IN (48777,48778,48779,48781,48782,48787,48791,48792,48810,48811,48812,48814,48819,48823,48824,48829,48830,48834,48914,48936,48941,48943,48944);

-- Helix Gearbreaker only spawns on the Lumbering Oaf, so his loot was never added
UPDATE `creature_template` SET `lootid`=47296 WHERE `entry`=47296;
UPDATE `creature_template` SET `lootid`=48940 WHERE `entry`=48940;
DELETE FROM `creature_loot_template` WHERE `entry` IN (47296,48940);

-- Glubtok's heroic fire wall platter: scripted rotation instead of an always-on waypoint path
UPDATE `creature_template` SET `ScriptName`='npc_glubtok_firewall_platter' WHERE `entry`=48974;
UPDATE `creature` SET `MovementType`=0 WHERE `guid`=8203546;
UPDATE `creature_addon` SET `path_id`=0 WHERE `guid`=8203546;
DELETE FROM `waypoint_data` WHERE `id`=82035460;
-- The fire wall burns above the floor, so its fires have to stay airborne
UPDATE `creature_template` SET `InhabitType`=7 WHERE `entry` IN (48976,49041,49042);

-- Glubtok's kill line shared a text group with "Glubtok ready?"
UPDATE `creature_text` SET `groupid`=8, `id`=0 WHERE `entry`=47162 AND `groupid`=3 AND `text`='''Sploded dat one!';

-- Glubtok's Arcane Fire/Frost Beams are channelled by the blossom bunnies at Glubtok
DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId`=13 AND `SourceEntry` IN (88072,88093);

-- Fire/Frost Blossom only summon their adds on heroic; the fire wall's filler fires only burn for show
DELETE FROM `spell_script_names` WHERE `spell_id` IN (87925,88129,88169,91397,91398);

-- Mining Powder: stationary explosive, never chases its attacker
UPDATE `creature_template` SET `AIName`='NullCreatureAI', `unit_flags`=`unit_flags`|131072, `unit_flags2`=2048 WHERE `entry` IN (48284,48835);
